1	/**
2	 * StatusList2021 manager.
3	 * - Maintains a bitstring of revoked credential indices (stored in data/statuslist.json)
4	 * - Serves a signed StatusList2021 credential at /status/{listId}
5	 * - Each issued credential gets an index; revocation flips the bit
6	 * - Auto-refresh: re-signs and re-publishes the list on any revocation
7	 *
8	 * Spec: https://www.w3.org/TR/vc-status-list/
9	 */
10	import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'fs';
11	import { randomUUID } from 'crypto';
12	import { SignJWT } from 'jose';
13	import { getIssuerKeyPair } from '../keys/manager.js';
14	import { loadConfig } from '../config/loader.js';
15	
16	function getPaths() {
17	  const dataDir = process.env.DATA_DIR ?? './data';
18	  return {
19	    dataDir,
20	    statusPath: `${dataDir}/statuslist.json`,
21	  };
22	}
23	const LIST_SIZE = 131072; // 16KB bitstring = 131072 credential slots
24	
25	// Cache for the signed StatusList JWT to avoid re-signing on every request
26	let cachedStatusListJWT: { jwt: string; revokedIndicesHash: string; timestamp: number } | null = null;
27	const STATUSLIST_CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes cache TTL
28	
29	interface StatusListStore {
30	  listId: string;
31	  nextIndex: number;
32	  revokedIndices: number[];
33	  issuedCredentials: Array<{
34	    credentialId: string;
35	    holderEmail: string;
36	    statusIndex: number;
37	    issuedAt: string;
38	    revoked: boolean;
39	    revokedAt?: string;
40	  }>;
41	}
42	
43	function loadStore(): StatusListStore {
44	  const { dataDir, statusPath } = getPaths();
45	  if (!existsSync(dataDir)) mkdirSync(dataDir, { recursive: true });
46	  if (existsSync(statusPath)) {
47	    return JSON.parse(readFileSync(statusPath, 'utf-8')) as StatusListStore;
48	  }
49	  const store: StatusListStore = {
50	    listId: randomUUID(),
51	    nextIndex: 0,
52	    revokedIndices: [],
53	    issuedCredentials: [],
54	  };
55	  writeFileSync(statusPath, JSON.stringify(store, null, 2));
56	  return store;
57	}
58	
59	function saveStore(store: StatusListStore): void {
60	  const { statusPath } = getPaths();
61	  writeFileSync(statusPath, JSON.stringify(store, null, 2));
62	}
63	
64	function buildBitstring(revokedIndices: number[]): string {
65	  const bytes = new Uint8Array(Math.ceil(LIST_SIZE / 8));
66	  for (const idx of revokedIndices) {
67	    const byteIndex = Math.floor(idx / 8);
68	    const bitIndex = idx % 8;
69	    bytes[byteIndex] |= (1 << bitIndex);
70	  }
71	  return Buffer.from(bytes).toString('base64url');
72	}
73	
74	/** Assign a status list index to a new credential. Returns { listId, statusIndex }. */
75	export function assignStatusIndex(credentialId: string, holderEmail: string): { listId: string; statusIndex: number } {
76	  const store = loadStore();
77	  if (store.nextIndex >= LIST_SIZE) throw new Error('StatusList full — create a new list');
78	
79	  const statusIndex = store.nextIndex++;
80	  store.issuedCredentials.push({
81	    credentialId,
82	    holderEmail,
83	    statusIndex,
84	    issuedAt: new Date().toISOString(),
85	    revoked: false,
86	  });
87	  saveStore(store);
88	  return { listId: store.listId, statusIndex };
89	}
90	
91	/** Revoke a credential by ID. Returns true if found and revoked. */
92	export function revokeCredential(credentialId: string, reason: string = 'Administrative Revocation'): boolean {
93	  const store = loadStore();
94	  const entry = store.issuedCredentials.find(c => c.credentialId === credentialId);
95	  if (!entry || entry.revoked) return false;
96	
97	  const revokedAt = new Date().toISOString();
98	  entry.revoked = true;
99	  entry.revokedAt = revokedAt;
100	  
101	  // Only add to revokedIndices if not already there
102	  if (!store.revokedIndices.includes(entry.statusIndex)) {
103	    store.revokedIndices.push(entry.statusIndex);
104	  }
105	  saveStore(store);
106	
107	  // Invalidate cache to force re-signing on next request
108	  cachedStatusListJWT = null;
109	
110	  // Audit logging (simulated as console log, could be a separate file/DB)
111	  console.log(`[audit] REVOKE: Credential ${credentialId} (Index ${entry.statusIndex}) revoked at ${revokedAt}. Reason: ${reason}`);
112	
113	  return true;
114	}
115	
116	/** Get all issued credentials for admin view. */
117	export function getIssuedCredentials() {
118	  return loadStore().issuedCredentials;
119	}
120	
121	/** Search issued credentials by various criteria. */
122	export function searchCredentials(query: string): StatusListStore['issuedCredentials'] {
123	  const store = loadStore();
124	  const q = query.toLowerCase().trim();
125	  
126	  if (!q) {
127	    return store.issuedCredentials;
128	  }
129	
130	  return store.issuedCredentials.filter(cred => {
131	    // Search by credential ID
132	    if (cred.credentialId.toLowerCase().includes(q)) return true;
133	    
134	    // Search by holder email
135	    if (cred.holderEmail.toLowerCase().includes(q)) return true;
136	    
137	    // Search by status
138	    if (cred.revoked && q.includes('revoked')) return true;
139	    if (!cred.revoked && q.includes('active')) return true;
140	    
141	    // Search by date (issuedAt)
142	    if (cred.issuedAt && cred.issuedAt.toLowerCase().includes(q)) return true;
143	    
144	    // Search by revokedAt
145	    if (cred.revokedAt && cred.revokedAt.toLowerCase().includes(q)) return true;
146	    
147	    return false;
148	  });
149	}
150	
151	/** Get credential by ID. */
152	export function getCredentialById(credentialId: string) {
153	  const store = loadStore();
154	  return store.issuedCredentials.find(c => c.credentialId === credentialId);
155	}
156	
157	/** Get the current list ID. */
158	export function getListId(): string {
159	  return loadStore().listId;
160	}
161	
162	/** Build and sign a StatusList2021 VC. Served at /status/{listId}. */
163	export async function buildStatusListJWT(): Promise<string> {
164	  const store = loadStore();
165	  const { privateKey, kid } = await getIssuerKeyPair();
166	  const config = loadConfig();
167	
168	  const bitstring = buildBitstring(store.revokedIndices);
169	  const now = Math.floor(Date.now() / 1000);
170	
171	  const revokedIndicesHash = store.revokedIndices.sort((a, b) => a - b).join(',');
172	  
173	  // Check cache validity
