71	export function createCredentialRouter(pseudonymSecret: string): Router {
72	  const router = createRouter();
73	
74	  router.post('/credentials', async (req, res) => {
75	    const auth = req.headers.authorization;
76	    if (!auth?.startsWith('Bearer ')) { res.status(401).json({ error: 'unauthorized' }); return; }
77	
78	    const rawToken = REDACTED;
79	    const tokenEntry = lookupAccessToken(rawToken);
80	    if (!tokenEntry) { res.status(401).json({ error: 'invalid_token' }); return; }
81	
82	    const { holderData, cNonce, cNonceExpiresAt } = tokenEntry;
83	    const config = loadConfig();
84	    const { privateKey, kid } = await getIssuerKeyPair();
85	
86	    // ── Holder Proof-of-Possession ──────────────────────────────────────────
87	    const body = req.body as Record<string, unknown>;
88	    const proof = body['proof'] as Record<string, string> | undefined;
89	    const isDemoMode = process.env['DEMO_MODE'] === 'true';
90	
91	    let holderThumbprint: string;
92	    let holderJwk: Record<string, unknown> | undefined;
93	
94	    if (proof?.['proof_type'] === 'jwt' && proof['jwt']) {
95	      // Verify c_nonce has not expired
96	      if (Date.now() > cNonceExpiresAt) {
97	        res.status(400).json({ error: 'use_dpop_nonce', c_nonce: cNonce, c_nonce_expires_in: 0 });
98	        return;
99	      }
100	
101	      try {
102	        const result = await verifyHolderProofJwt(proof['jwt'], config.issuer.url, cNonce);
103	        holderThumbprint = result.holderThumbprint;
104	        holderJwk = result.jwk as unknown as Record<string, unknown>;
105	      } catch (e) {
106	        const code = e instanceof ProofVerificationError ? e.code : 'invalid_proof';
107	        const msg = (e as Error).message;
108	        console.warn('[issuer] Holder proof rejected:', msg);
109	        logInterop({ type: 'error', category: 'proof', message: msg, details: { code } });
110	        res.status(400).json({ error: code, error_description: msg });
111	        return;
112	      }
113	    } else if (isDemoMode) {
114	      // DEMO_MODE only: anonymous fallback — no holder binding
115	      console.warn('[issuer] DEMO_MODE: issuing credential without holder proof (no binding)');
116	      holderThumbprint = 'anonymous';
117	      holderJwk = undefined;
118	    } else {
119	      // Production: holder proof is required — fail closed
120	      res.status(400).json({
121	        error: 'holder_binding_required',
122	        error_description: 'A proof-of-possession JWT is required. Set DEMO_MODE=true to disable for testing.',
123	        c_nonce: cNonce,
124	        c_nonce_expires_in: Math.max(0, Math.floor((cNonceExpiresAt - Date.now()) / 1000)),
125	      });
126	      return;
127	    }
128	
129	    // ── Template resolution ─────────────────────────────────────────────────
130	    let template;
131	    const credentialType = tokenEntry.credentialType ?? config.credential.type;
132	    try {
133	      template = getTemplate(credentialType);
134	    } catch (e) {
135	      res.status(500).json({ error: 'unsupported_credential_type', detail: (e as Error).message });
136	      return;
137	    }
138	
139	    // A claims snapshot present on the token entry means this code went
140	    // through the consent gate: issue exactly what the holder reviewed
141	    // and approved, never recompute live (see token.ts's issuePreAuthCode).
142	    // Otherwise (the non-consent path, unchanged from before this existed)
143	    // compute claims live from the current config/mappings.
144	    let claims: Record<string, unknown>;
145	    if (tokenEntry.claims) {
146	      claims = tokenEntry.claims;
147	    } else {
148	      const { mappedData, errors: mappingErrors } = resolveMappedData(template, config.fieldMappings ?? {}, holderData);
149	      if (mappingErrors.length > 0) {
150	        logInterop({ type: 'warning', category: 'issuance', message: 'Field mapping failed', details: { errors: mappingErrors } });
151	        res.status(400).json({ error: 'invalid_field_mappings', detail: mappingErrors });
152	        return;
153	      }
154	
155	      try {
156	        claims = template.buildClaims(mappedData, config.templateOptions);
157	      } catch (e) {
158	        console.error('[issuer] buildClaims error:', e);
159	        res.status(400).json({ error: 'claim_build_failed', detail: (e as Error).message });
160	        return;
161	      }
162	    }
163	
164	    // ── SD-JWT selective disclosure ─────────────────────────────────────────
165	    const { sdHashes, disclosures } = buildSdJwtPayload(claims);
