170	    const { listId, statusIndex } = assignStatusIndex(credentialId, holderEmail);
171	
172	    // ── Pairwise pseudonym — uses verified thumbprint ───────────────────────
173	    const pseudonym = pairwisePseudonym(pseudonymSecret, holderThumbprint, config.issuer.did, credentialType);
174	
175	    const now = Math.floor(Date.now() / 1000);
176	    const exp = now + config.credential.expiresInDays * 86400;
177	
178	    /**
179	     * SD-JWT-VC JWT payload (draft-ietf-oauth-sd-jwt-vc):
180	     * - cnf.jkt: JWK thumbprint — binds credential to holder key
181	     * - _sd_alg, _sd: selective disclosure per IETF SD-JWT spec
182	     * - No raw claim values in payload
