  ? { credentials: issued.map(c => ({ credential: c.credential })) }
  : { credential: issued[0]!.credential, format };
logInterop({
  type: 'info',
  category: 'issuance',
  message: `Issued ${issued.length}x ${credentialType}`,
  details: { credentialIds: issued.map(c => c.credentialId), holderEmail },
});

