/**
 * Token Status List manager (IETF draft-ietf-oauth-status-list).
 * - Maintains a 1-bit list of revoked credential indices (stored in data/statuslist.json)
 * - Serves a signed Status List Token (typ "statuslist+jwt") at /status/{listId}
 * - Each issued credential gets a RANDOM unused index, so the index reveals
 *   nothing about issuance order and can't be used to link batch copies
 * - Copies issued together share a batchId (issuer-side only, never in the
 *   credential); revoking one copy revokes the whole batch
 * - Auto-refresh: re-signs and re-publishes the list on any revocation
 *
 * The German EUDI ecosystem requires Token Status Lists for SD-JWT VC.
 */
import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'fs';
import { randomInt, randomUUID } from 'crypto';
import { deflateSync } from 'zlib';
import { SignJWT } from 'jose';
import { getIssuerKeyPair } from '../keys/manager.js';
import { loadConfig } from '../config/loader.js';

function getPaths() {
  const dataDir = process.env.DATA_DIR ?? './data';
  return {
    dataDir,
    statusPath: `${dataDir}/statuslist.json`,
  };
}
const LIST_SIZE = 131072; // 16KB bitstring = 131072 credential slots

// Cache for the signed StatusList JWT to avoid re-signing on every request
let cachedStatusListJWT: { jwt: string; revokedIndicesHash: string; timestamp: number } | null = null;
const STATUSLIST_CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes cache TTL
/** Seconds verifiers may cache the list before fetching again (Token Status List `ttl`). */
const STATUSLIST_TTL_S = 300;
/** Lifetime of one signed Status List Token. */
const STATUSLIST_EXP_S = 24 * 3600;

interface StatusListStore {
  listId: string;
  /** Legacy sequential counter from before random indices; no longer used. */
  nextIndex?: number;
  revokedIndices: number[];
  issuedCredentials: Array<{
    credentialId: string;
    holderEmail: string;
    statusIndex: number;
    /** Copies issued together in one batch; revoked together. */
    batchId?: string;
    issuedAt: string;
    revoked: boolean;
    revokedAt?: string;
  }>;
}

function loadStore(): StatusListStore {
  const { dataDir, statusPath } = getPaths();
  if (!existsSync(dataDir)) mkdirSync(dataDir, { recursive: true });
  if (existsSync(statusPath)) {
    return JSON.parse(readFileSync(statusPath, 'utf-8')) as StatusListStore;
  }
  const store: StatusListStore = {
    listId: randomUUID(),
    revokedIndices: [],
    issuedCredentials: [],
  };
  writeFileSync(statusPath, JSON.stringify(store, null, 2));
  return store;
}

function saveStore(store: StatusListStore): void {
  const { statusPath } = getPaths();
  writeFileSync(statusPath, JSON.stringify(store, null, 2));
}

function buildBitstring(revokedIndices: number[]): string {
  const bytes = new Uint8Array(Math.ceil(LIST_SIZE / 8));
  for (const idx of revokedIndices) {
    const byteIndex = Math.floor(idx / 8);
    const bitIndex = idx % 8;
    bytes[byteIndex] |= (1 << bitIndex);
  }
  return Buffer.from(bytes).toString('base64url');
}

/** Pick a uniformly random index not yet used in this list. */
function pickRandomFreeIndex(used: Set<number>): number {
  if (used.size >= LIST_SIZE) throw new Error('StatusList full — create a new list');
  // Random probing is fast while the list is mostly free; fall back to a
  // scan from a random start so a nearly full list still terminates.
  for (let attempt = 0; attempt < 64; attempt++) {
    const idx = randomInt(LIST_SIZE);
    if (!used.has(idx)) return idx;
  }
  const start = randomInt(LIST_SIZE);
  for (let i = 0; i < LIST_SIZE; i++) {
    const idx = (start + i) % LIST_SIZE;
    if (!used.has(idx)) return idx;
  }
  throw new Error('StatusList full — create a new list');
}

/**
 * Assign a random status list index to a new credential. Returns { listId, statusIndex }.
 * Pass the same batchId for copies issued together so they are revoked together.
 */
export function assignStatusIndex(
  credentialId: string,
  holderEmail: string,
  batchId?: string,
): { listId: string; statusIndex: number } {
  const store = loadStore();
  const used = new Set(store.issuedCredentials.map(c => c.statusIndex));
  const statusIndex = pickRandomFreeIndex(used);
  store.issuedCredentials.push({
    credentialId,
    holderEmail,
    statusIndex,
    ...(batchId ? { batchId } : {}),
    issuedAt: new Date().toISOString(),
    revoked: false,
  });
  saveStore(store);
  return { listId: store.listId, statusIndex };
}

/**
 * Revoke a credential by ID, together with every other copy from its batch.
 * Returns true if found and revoked.
 */
export function revokeCredential(credentialId: string, reason: string = 'Administrative Revocation'): boolean {
  const store = loadStore();
  const entry = store.issuedCredentials.find(c => c.credentialId === credentialId);
  if (!entry || entry.revoked) return false;

  const revokedAt = new Date().toISOString();
  const targets = entry.batchId
    ? store.issuedCredentials.filter(c => c.batchId === entry.batchId && !c.revoked)
    : [entry];

  for (const t of targets) {
    t.revoked = true;
    t.revokedAt = revokedAt;
    if (!store.revokedIndices.includes(t.statusIndex)) {
      store.revokedIndices.push(t.statusIndex);
    }
  }
  saveStore(store);

  // Invalidate cache to force re-signing on next request
  cachedStatusListJWT = null;

  // Audit logging (simulated as console log, could be a separate file/DB)
  console.log(`[audit] REVOKE: Credential ${credentialId} (${targets.length} cop${targets.length === 1 ? 'y' : 'ies'}) revoked at ${revokedAt}. Reason: ${reason}`);

  return true;
}

/** Get all issued credentials for admin view. */
export function getIssuedCredentials() {
  return loadStore().issuedCredentials;
}

/** Search issued credentials by various criteria. */
export function searchCredentials(query: string): StatusListStore['issuedCredentials'] {
  const store = loadStore();
  const q = query.toLowerCase().trim();

  if (!q) {
    return store.issuedCredentials;
  }

  return store.issuedCredentials.filter(cred => {
    // Search by credential ID
    if (cred.credentialId.toLowerCase().includes(q)) return true;

    // Search by holder email
    if (cred.holderEmail.toLowerCase().includes(q)) return true;

    // Search by status
    if (cred.revoked && q.includes('revoked')) return true;
    if (!cred.revoked && q.includes('active')) return true;

    // Search by date (issuedAt)
    if (cred.issuedAt && cred.issuedAt.toLowerCase().includes(q)) return true;

    // Search by revokedAt
    if (cred.revokedAt && cred.revokedAt.toLowerCase().includes(q)) return true;

    return false;
  });
}

/** Get credential by ID. */
export function getCredentialById(credentialId: string) {
  const store = loadStore();
  return store.issuedCredentials.find(c => c.credentialId === credentialId);
}

/** Get the current list ID. */
export function getListId(): string {
  return loadStore().listId;
}

/** URI of the current status list; must match `sub` of the Status List Token. */
export function getStatusListUri(): string {
  return `${loadConfig().issuer.url}/status/${getListId()}`;
}

/**
 * Build and sign a Status List Token (draft-ietf-oauth-status-list).
 * Served at /status/{listId}. `lst` is the ZLIB-compressed 1-bit list,
 * index 0 in the least significant bit of byte 0; 1 = INVALID (revoked).
 */
export async function buildStatusListJWT(): Promise<string> {
  const store = loadStore();
  const { privateKey, kid } = await getIssuerKeyPair();
  const config = loadConfig();

  const now = Math.floor(Date.now() / 1000);

  const revokedIndicesHash = store.revokedIndices.sort((a, b) => a - b).join(',');

  // Check cache validity
  if (cachedStatusListJWT && 
      cachedStatusListJWT.revokedIndicesHash === revokedIndicesHash &&
      Date.now() - cachedStatusListJWT.timestamp < STATUSLIST_CACHE_TTL_MS) {
    return cachedStatusListJWT.jwt;
  }

  const bitstring = Buffer.from(buildBitstring(store.revokedIndices), 'base64url');
  const jwt = await new SignJWT({
    iss: config.issuer.did,
    sub: `${config.issuer.url}/status/${store.listId}`,
    iat: now,
    exp: now + STATUSLIST_EXP_S,
    ttl: STATUSLIST_TTL_S,
    status_list: {
      bits: 1,
      lst: deflateSync(bitstring).toString('base64url'),
    },
  })
    .setProtectedHeader({ alg: 'ES256', kid, typ: 'statuslist+jwt' })
    .sign(privateKey);

  // Cache the signed JWT
  cachedStatusListJWT = {
    jwt,
    revokedIndicesHash,
    timestamp: Date.now()
  };

  return jwt;
}

/**
 * Unlinkability by default (OID4VCI 1.0 batch issuance + IETF Token Status List).
 *
 * Requirement: copies of one credential issued in a batch must share no value
 * a verifier could use to link two presentations, apart from what every
 * credential of that type and day carries anyway (issuer, type, day-rounded
 * timestamps, status list URI, digest algorithm).
 */
import { describe, it, expect, beforeAll } from 'vitest';
import { generateKeyPair, exportJWK, SignJWT, jwtVerify, decodeProtectedHeader } from 'jose';
import { mkdirSync, existsSync, writeFileSync, rmSync } from 'fs';
import { loadSecrets } from '../../config/secrets.js';
import { getIssuerKeyPair } from '../../keys/manager.js';
import { statusAt } from '../../revocation/__tests__/token-status-helpers.js';

const PORT = 3515;
const serverUrl = `http://localhost:${PORT}`;
const adminApiKey = REDACTED;

/** Values every copy of a credential type legitimately has in common. */
const SHAREABLE_KEYS = new Set(['iss', 'vct', 'iat', 'exp', '_sd_alg', 'uri']);

async function newProof(cNonce: string) {
  const keys = await generateKeyPair('ES256');
  return new SignJWT({ aud: serverUrl, iat: Math.floor(Date.now() / 1000), nonce: cNonce })
    .setProtectedHeader({ alg: 'ES256', typ: 'openid4vci-proof+jwt', jwk: await exportJWK(keys.publicKey) })
    .sign(keys.privateKey);
}

async function getToken(): Promise<{ accessToken: string; cNonce: string }> {
  const offerRes = await fetch(`${serverUrl}/offer`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${adminApiKey}` },
    body: JSON.stringify({ holderId: 'batch-holder-01', credentialType: 'AgeCredential' }),
  });
  expect(offerRes.status).toBe(200);
  const offer = (await offerRes.json() as any).offer;
  const code = offer.grants['urn:ietf:params:oauth:grant-type:pre-authorized_code']['pre-authorized_code'];
  const tokenRes = await fetch(`${serverUrl}/token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ grant_type: 'urn:ietf:params:oauth:grant-type:pre-authorized_code', 'pre-authorized_code': code }),
  });
  expect(tokenRes.status).toBe(200);
  const t = await tokenRes.json() as any;
  return { accessToken: t.access_token, cNonce: t.c_nonce };
}

function requestCredential(accessToken: string, body: unknown) {
  return fetch(`${serverUrl}/credentials`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${accessToken}` },
    body: JSON.stringify(body),
  });
}

/** Flatten every scalar in a JSON value into "key=value" strings. */
function leafValues(value: unknown, key = ''): string[] {
  if (Array.isArray(value)) return value.flatMap(v => leafValues(v, key));
  if (value && typeof value === 'object') {
    return Object.entries(value).flatMap(([k, v]) => leafValues(v, k));
  }
  return SHAREABLE_KEYS.has(key) ? [] : [`${key}=${String(value)}`];
}

async function issueBatch(n: number): Promise<string[]> {
  const { accessToken, cNonce } = await getToken();
  const proofs = await Promise.all(Array.from({ length: n }, () => newProof(cNonce)));
  const res = await requestCredential(accessToken, {
    credential_configuration_id: 'AgeCredential',
    proofs: { jwt: proofs },
  });
  expect(res.status).toBe(200);
  const body = await res.json() as any;
  expect(body.credentials).toHaveLength(n);
  return body.credentials.map((c: { credential: string }) => c.credential);
}

describe('Unlinkable batch issuance', () => {
  beforeAll(async () => {
    const tempDir = './src/oid4vci/__tests__/temp-data-batch';
    if (existsSync(tempDir)) rmSync(tempDir, { recursive: true, force: true });
    mkdirSync(tempDir, { recursive: true });
    writeFileSync(`${tempDir}/holders.json`, JSON.stringify([
      { id: 'batch-holder-01', email: 'batch-holder@example.com', dateOfBirth: '2000-01-01' },
    ]));
    process.env['DATA_DIR'] = tempDir;
    process.env['ISSUER_URL'] = serverUrl;
    process.env['PORT'] = String(PORT);
    await import('../../server.js');
    await new Promise(resolve => setTimeout(resolve, 500));
  });

  it('advertises batch issuance and the dc+sd-jwt format in issuer metadata', async () => {
    const meta = await (await fetch(`${serverUrl}/.well-known/openid-credential-issuer`)).json() as any;
    expect(meta.batch_credential_issuance.batch_size).toBeGreaterThanOrEqual(2);
    expect(meta.credential_configurations_supported.AgeCredential.format).toBe('dc+sd-jwt');
  });

  it('issues one dc+sd-jwt copy per proof, with no linkable value shared between copies', async () => {
    const credentials = await issueBatch(3);
    const { publicKey } = await getIssuerKeyPair();

    const perCopy: Set<string>[] = [];
    const iats = new Set<number>();
    for (const credential of credentials) {
      const [jwt, ...disclosures] = credential.split('~').filter(Boolean);
      expect(decodeProtectedHeader(jwt!).typ).toBe('dc+sd-jwt');
      const { payload } = await jwtVerify(jwt!, publicKey);

      // IETF Token Status List reference, not W3C StatusList2021
      expect(payload['credentialStatus']).toBeUndefined();
      const ref = (payload['status'] as any)?.status_list;
      expect(Number.isInteger(ref.idx)).toBe(true);
      expect(ref.uri).toBe(`${serverUrl}/status/${ref.uri.split('/').pop()}`);

      // Timestamps rounded to the UTC day, so issuance time can't link copies
      expect((payload.iat as number) % 86400).toBe(0);
      iats.add(payload.iat as number);

      perCopy.push(new Set([...leafValues(payload), ...disclosures.map(d => `disclosure=${d}`)]));
    }

    expect(iats.size).toBe(1);
    for (let i = 0; i < perCopy.length; i++) {
      for (let j = i + 1; j < perCopy.length; j++) {
        const shared = [...perCopy[i]!].filter(v => perCopy[j]!.has(v));
        expect(shared).toEqual([]);
      }
    }
  });

  it('rejects a batch that reuses one holder key (copies would be linkable via cnf)', async () => {
    const { accessToken, cNonce } = await getToken();
    const proof = await newProof(cNonce);
    const res = await requestCredential(accessToken, { proofs: { jwt: [proof, proof] } });
    expect(res.status).toBe(400);
    expect((await res.json() as any).error).toBe('invalid_proof');
  });

  it('rejects a batch larger than the advertised batch_size', async () => {
    const meta = await (await fetch(`${serverUrl}/.well-known/openid-credential-issuer`)).json() as any;
    const { accessToken, cNonce } = await getToken();
    const proofs = await Promise.all(
      Array.from({ length: meta.batch_credential_issuance.batch_size + 1 }, () => newProof(cNonce)),
    );
    const res = await requestCredential(accessToken, { proofs: { jwt: proofs } });
    expect(res.status).toBe(400);
    expect((await res.json() as any).error).toBe('invalid_credential_request');
  });

  it('publishes a Token Status List, and revoking one copy revokes the whole batch', async () => {
    const credentials = await issueBatch(2);
    const { publicKey } = await getIssuerKeyPair();
    const payloads = await Promise.all(credentials.map(async c => (await jwtVerify(c.split('~')[0]!, publicKey)).payload));
    const refs = payloads.map(p => (p['status'] as any).status_list as { idx: number; uri: string });

    const fetchList = async () => {
      const res = await fetch(refs[0]!.uri);
      expect(res.status).toBe(200);
      expect(res.headers.get('content-type')).toContain('application/statuslist+jwt');
      const jwt = await res.text();
      expect(decodeProtectedHeader(jwt).typ).toBe('statuslist+jwt');
      const { payload } = await jwtVerify(jwt, publicKey);
      expect(payload.sub).toBe(refs[0]!.uri);
      expect((payload['status_list'] as any).bits).toBe(1);
      return (payload['status_list'] as any).lst as string;
    };

    const before = await fetchList();
    for (const r of refs) expect(statusAt(before, r.idx)).toBe(0);

    const revokeRes = await fetch(`${serverUrl}/admin/revoke`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${adminApiKey}` },
      body: JSON.stringify({ credentialId: payloads[0]!.jti, reason: 'batch revocation test' }),
    });
    expect((await revokeRes.json() as any).success).toBe(true);

    const after = await fetchList();
    for (const r of refs) expect(statusAt(after, r.idx)).toBe(1);
  });
});

